import inspect
import six
import sys


def get_call_args(func, args, kwargs):
    """Get the actual value bounded to each formal parameter when calling
    `func(*args, **kwargs)`.

    It works for methods too (bounded, unbounded, staticmethods, classmethods).

    @returns: a mapping of every formal parameter (including *varargs
           and **kwargs if present) of the function to the respective bounded value.

    Examples::
        >>> def func(a, b='foo', c=None, *x, **y):
        ...     pass
        >>> get_call_args(func, 5)
        {'a': 5, 'y': {}, 'c': None, 'b': 'foo', 'x': ()}
        >>> get_call_args(func, 5, 'foo')
        {'a': 5, 'y': {}, 'c': None, 'b': 'foo', 'x': ()}
        >>> get_call_args(func, 5, c=['a', 'b'])
        {'a': 5, 'y': {}, 'c': ['a', 'b'], 'b': 'foo', 'x': ()}
        >>> get_call_args(func, 5, 6, 7, 8)
        {'a': 5, 'y': {}, 'c': 7, 'b': 6, 'x': (8,)}
        >>> get_call_args(func, 5, z=3, b=2)
        {'a': 5, 'y': {'z': 3}, 'c': None, 'b': 2, 'x': ()}

    Stolen from http://code.activestate.com/recipes/551779/
    """
    kwargs = kwargs.copy()
    arg2value = {}
    f_name = func.func_name if six.PY2 else func.__name__
    spec_args, varargs, varkw, defaults = inspect.getargspec(func)
    num_args = len(args)
    has_kwds = bool(kwargs)
    num_spec_args = len(spec_args)
    num_defaults = len(defaults or ())
    _handle_self_or_cls(arg2value, args, func, f_name, spec_args)
    _handle_positional_args(arg2value, args, spec_args)
    _handle_expected_named_args(arg2value, f_name, kwargs, spec_args)
    _handle_defaults(arg2value, defaults, num_defaults, spec_args)
    _check_for_missing_args(arg2value, f_name, has_kwds, num_args, num_defaults, num_spec_args, spec_args)
    _handle_remaining_named_args(arg2value, f_name, kwargs, varkw)
    _handle_remaining_positional_args(arg2value, args, defaults, f_name, num_args, num_spec_args, varargs)
    return arg2value


def _handle_self_or_cls(arg2value, args, func, f_name, spec_args):
    if _is_method(func):
        if _is_bound(func):
            arg2value[spec_args.pop(0)] = func.__self__
        elif not args or not isinstance(args[0], _get_class(func)):
            got = args and ('%s instance' % type(args[0]).__name__) or 'nothing'
            raise TypeError('unbound method %s() must be called with %s instance '
                            'as first argument (got %s instead)' %
                            (f_name, _get_class(func).__name__, got))


def _is_method(func):
    if six.PY2:
        output = inspect.ismethod(func)
    else:
        # unbounded method no longer exists in Python 3, it is counted as a function.
        # Therefore, inspect.ismethod() will return False if the method is "unbounded".
        # This is a work around to detect "unbounded" methods in Python 3
        spec = inspect.getargspec(func)
        has_self = len(spec.args) > 0 and spec.args[0] == 'self'
        output = inspect.ismethod(func) or inspect.isfunction(func) and has_self
    return output


def _is_bound(func):
    return func.__self__ is not None if six.PY2 else inspect.ismethod(func)


def _get_class(func):
    if six.PY2:
        return func.im_class
    elif inspect.ismethod(func):
        return func.__self__.__class__
    else:
        cls = getattr(inspect.getmodule(func), func.__qualname__.split('.<locals>', 1)[0].rsplit('.', 1)[0])
        return cls if isinstance(cls, type) else None


def _handle_positional_args(arg2value, args, spec_args):
    arg2value.update(six.moves.zip(spec_args, args))


def _handle_expected_named_args(arg2value, f_name, kwargs, spec_args):
    for arg in spec_args:
        if arg in kwargs:
            if arg in arg2value:
                raise TypeError("%s() got multiple values for keyword argument '%s'" % (f_name, arg))
            else:
                arg2value[arg] = kwargs.pop(arg)


def _handle_defaults(arg2value, defaults, num_defaults, spec_args):
    if defaults:
        for arg, val in six.moves.zip(spec_args[-num_defaults:], defaults):
            if arg not in arg2value:
                arg2value[arg] = val


def _check_for_missing_args(arg2value, f_name, has_kwds, num_args, num_defaults, num_spec_args, spec_args):
    for arg in spec_args:
        if arg not in arg2value:
            num_required = num_spec_args - num_defaults
            raise TypeError('%s() takes at least %d %s argument%s (%d given)'
                            % (f_name, num_required,
                               has_kwds and 'non-keyword ' or '',
                               num_required > 1 and 's' or '', num_args))


def _handle_remaining_named_args(arg2value, f_name, kwargs, varkw):
    if varkw:
        arg2value[varkw] = frozenset(kwargs)
    elif kwargs:
        raise TypeError("%s() got an unexpected keyword argument '%s'" % (f_name, six.next(kwargs)))


def _handle_remaining_positional_args(arg2value, args, defaults, f_name, num_args, num_spec_args, varargs):
    if varargs:
        if num_args > num_spec_args:
            arg2value[varargs] = tuple(args[-(num_args - num_spec_args):])
        else:
            arg2value[varargs] = ()
    elif num_spec_args < num_args:
        raise TypeError('%s() takes %s %d argument%s (%d given)' %
                        (f_name, defaults and 'at most' or 'exactly',
                         num_spec_args, num_spec_args > 1 and 's' or '', num_args))
